{"code":"def transform(grid):
    a=[r[:] for r in grid]; H=len(a); W=len(a[0])
    # horizontal colored runs (nonzero, non-2), process by row
    obs=[]
    for r in range(H):
        c=0
        while c<W:
            if a[r][c] not in (0,2):
                s=c; col=a[r][c]
                while c<W and a[r][c]==col: c+=1
                if c-s>=2: obs.append((r,s,c-1))
            else:c+=1
    obs.sort(); p=None
    for k,(r,s,e) in enumerate(obs):
        if p is None:
            # first encountered object sets course to its right side (or left at boundary)
            q=e+1 if e+1<W else s-1
            p0=q
            # source position
            for rr in range(r):
                if 2 in a[rr]: p0=a[rr].index(2); break
            if r>0:
                lo,hi=sorted((p0,q))
                for cc in range(lo,hi+1):
                    if a[r-1][cc]==0:a[r-1][cc]=2
            p=q
        elif s<=p<=e:
            q=e+1 if e+1<W else s-1
            if r>0:
                for cc in range(min(p,q),max(p,q)+1):
                    if a[r-1][cc]==0:a[r-1][cc]=2
            p=q
        # draw vertical to just above next event / end, but don't overwrite objects
        end=(obs[k+1][0]-1 if k+1<len(obs) else H-1)
        for rr in range((0 if k==0 else obs[k-1][0]+0),end+1):
            if a[rr][p]==0:a[rr][p]=2
    return a"}

